pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address constant OWNER = address(uint160(0xE0A));

    function setUp() public {
        address __invmut_eoa = address(uint160(0xE0A));
        vm.deal(__invmut_eoa, 100 ether);
        vm.startPrank(__invmut_eoa, __invmut_eoa);
        c = new C(address(this), 0);
        vm.stopPrank();
    }

    function testFuzz_property(address actor) public {
