pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address ownerEoa;

    function setUp() public { address __invmut_eoa = address(uint160(0xE0A)); vm.deal(__invmut_eoa, 100 ether); vm.startPrank(__invmut_eoa, __invmut_eoa); c = new C(address(this), 0); vm.stopPrank(); ownerEoa = __invmut_eoa; }

    function testFuzz_property(uint256 amount, address actor) public {
        // Admissible domain: a positive donation from an ordinary external actor
        vm.assume(amount > 0 && amount < 100 ether);
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        vm.assume(actor != address(this));
        vm.assume(actor != ownerEoa);

        // Owner opens the contract to the public (both versions pass this call)
        vm.prank(ownerEoa);
        c.OpenToThePublic();

        // Rule: after opening, ANY address may donate ANY positive amount successfully
        vm.deal(actor, amount);
        vm.prank(actor);
        bool ok;
        try c.donate{value: amount}() {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok);
    }
}

