pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address ownerAddr = address(uint160(0xE0A));

    function setUp() public {
        address __invmut_eoa = address(uint160(0xE0A));
        vm.deal(__invmut_eoa, 100 ether);
        vm.startPrank(__invmut_eoa, __invmut_eoa);
        c = new C(address(this), 0);
        vm.stopPrank();
    }

    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(uint160(actor) != 0xE0A);
        amount = bound(amount, 0, 1 ether);
        vm.deal(actor, amount + 1 ether);

        // owner opens the contract
        vm.prank(ownerAddr, ownerAddr);
        c.OpenToThePublic();

        // any real person (msg.sender == tx.origin) may donate any amount
        bool ok;
        vm.prank(actor, actor);
        try c.donate{value: amount}() { ok = true; } catch { ok = false; }

        assertTrue(ok, "contract must be open to the public after OpenToThePublic");
    }
}

