        vm.assume(actor != address(0));
        vm.assume(uint160(actor) != uint160(0xE0A));
        amount = bound(amount, 1, 1 ether);
        // owner opens the contract (reference: openToPublic = true; mutant keeps it false)
        vm.prank(owner_, owner_);
        c.OpenToThePublic();
        // any real person may then donate any amount; must succeed on reference
        vm.deal(actor, amount);
        bool ok;
        vm.prank(actor, actor);
        try c.donate{value: amount}() { ok = true; } catch { ok = false; }
        assertTrue(ok, "after OpenToThePublic, donation from any real person must succeed");
    }
}

