pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address ownerAddr = address(uint160(0xE0A));

    function setUp() public {
        address __invmut_eoa = ownerAddr;
        vm.deal(__invmut_eoa, 100 ether);
        vm.startPrank(__invmut_eoa, __invmut_eoa);
        c = new C(address(this), 0);
        vm.stopPrank();
    }

    function testFuzz_property(address actor) public {
        // Only EOAs can pass the onlyRealPeople modifier (msg.sender == tx.origin);
        // Foundry's vm.prank keeps them equal, but exclude addresses carrying code.
        vm.assume(actor.code.length == 0);
        vm.assume(actor != address(0));

        // Owner opens the contract to the public.
        vm.prank(ownerAddr);
        c.OpenToThePublic();

        // Any real person can now wager at the current bet limit (0 ether) without reverting.
        vm.deal(actor, 1 ether);
        vm.prank(actor);
        try c.wager{value: c.currentBetLimit()}() {
            assertTrue(c.hasPlayerWagered(actor), "contract must be open to the public after OpenToThePublic");
        } catch {
            assertTrue(false, "contract must be open to the public after OpenToThePublic");
        }
    }
}

