contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint256 newLimit) public payable {
        require(newLimit > 0);
        bool adjReverted;
        try c.AdjustBetAmounts(newLimit) { adjReverted = false; } catch { adjReverted = true; }
        bool openReverted;
        try c.OpenToThePublic() { openReverted = false; } catch { openReverted = true; }
        // Rule: every owner-gated entry point gates the same caller.
        // A caller that is blocked by OpenToThePublic (onlyOwner) must also be
        // blocked from AdjustBetAmounts (onlyOwner). The mutant drops the check
        // on AdjustBetAmounts, so a non-owner succeeds there while still being
        // blocked by OpenToThePublic.
        assert(adjReverted == openReverted);
    }
    receive() external payable { }
}

